#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8

int main(int argc, char *argv[]) {
    // Expect: prog n m u1 v1 u2 v2 ... um vm
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n <= 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }
    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0) {
        puts("INVALID_INPUT");
        return 1;
    }
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[MAXV][MAXV] = {0};
    int indeg[MAXV] = {0};
    bool done[MAXV] = {0};

    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        long v = strtol(argv[3 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        // ignore duplicate edges (they don't affect indegree if already present)
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indeg[v]++;
        }
    }

    int order[MAXV];
    int out_idx = 0;
    // Kahn's algorithm
    while (out_idx < n) {
        int v = -1;
        for (int i = 0; i < n; ++i) {
            if (!done[i] && indeg[i] == 0) {
                v = i;
                break;
            }
        }
        if (v == -1) {
            puts("CYCLE");
            return 0;
        }
        done[v] = true;
        order[out_idx++] = v;
        // decrease indegree of neighbors
        for (int j = 0; j < n; ++j) {
            if (adj[v][j]) {
                indeg[j]--;
            }
        }
    }

    for (int i = 0; i < out_idx; ++i) {
        if (i) putchar(' ');
        printf("%d", order[i]);
    }
    putchar('\n');
    return 0;
}
